    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def max_value_on_paths(N, grid_values):
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    :param N: The size of the grid (N x N).
    :param grid_values: A list of tuples where each tuple contains
        the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
        The list is terminated by a tuple with all zeros.
    :return: The maximum sum of values collected on the two paths.
    """

    # Initialize the grid with the values
    grid = []
    for i in range(N):
        grid.append([])
        for j in range(N):
            grid[i].append(0)
    for x, y, value in grid_values:
        grid[x][y] = value

    # Create a dictionary to store the maximum values
    # for each grid point
    max_values = {}
    for i in range(N):
        max_values[i] = {}
        for j in range(N):
            max_values[i][j] = 0

    # Iterate over the grid and calculate the maximum
    # values for each grid point
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 0:
                continue
            if i == 0 and j == 0:
                max_values[i][j] = grid[i][j]
            elif i == 0:
                max_values[i][j] = max(max_values[i][j-1], grid[i][j])
            elif j == 0:
                max_values[i][j] = max(max_values[i-1][j], grid[i][j])
            else:
                max_values[i][j] = max(max_values[i-1][j], max_values[i][j-1], grid[i][j])

    # Find the maximum value on two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            if max_sum < max_values[i][j] + max_values[i][N-1-j] + max_values[N-1-i][j] + max_values[N-1-i][N-1-j]:
                max_sum = max_values[i][j] + max_values[i][N-1-j] + max_values[N-1-i][j] + max_values[N-1-i][N-1-j]

    return max_sum

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.

    Example:
        >>> find_number_combinations()
        [(123, 246, 369), (124, 248, 372), ...]
    """
    nums = [1, 2, 3, 4, 5, 6, 7, 8, 9]
    combinations = []

    for i in range(3):
        for j in range(i + 1, 6):
            for k in range(j + 1, 10):
                if nums[i] * 2 == nums[j] and nums[i] * 3 == nums[k]:
                    combinations.append((nums[i], nums[j], nums[k]))

    return sorted(combinations)

